/usr/bin/gzip
/usr/bin/zcat
===
--- 01_seed.sql.gz ---

INSERT INTO categories (name) VALUES
('Games'), ('Music');

INSERT INTO products (name, price, category_id) VALUES
('Guitar', 199.99, 2),
('Board Game', 29.99, 1);

--- 02_schema.sql.gz ---

CREATE DATABASE IF NOT EXISTS benchmark_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE benchmark_db;

CREATE TABLE IF NOT EXISTS categories (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);

CREATE DEFINER=`devops`@`%` VIEW category_view AS
SELECT id, name FROM categories;

CREATE TABLE IF NOT EXISTS products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(20) NOT NULL,
    price DECIMAL(10, 2) NOT NULL,
    category_id INT,
    FOREIGN KEY (category_id) REFERENCES categories(id)
);

input.command:
mysql -uroot --socket=/var/run/mysqld/mysqld.sock <<'SQL'
-- Definer user referenced by category_view in the schema migration
CREATE USER IF NOT EXISTS 'devops'@'%' IDENTIFIED WITH mysql_native_password BY 'devops_pass';
CREATE USER IF NOT EXISTS 'devops'@'localhost' IDENTIFIED WITH mysql_native_password BY 'devops_pass';

-- Required benchmark user
CREATE USER IF NOT EXISTS 'benchmark_user'@'%' IDENTIFIED WITH mysql_native_password BY 'benchmark_pass';
CREATE USER IF NOT EXISTS 'benchmark_user'@'localhost' IDENTIFIED WITH mysql_native_password BY 'benchmark_pass';
FLUSH PRIVILEGES;
SQL
echo "users-rc=$?"

set -e
echo ">>> Applying 02_schema.sql.gz (schema must precede seed)"
zcat /testbed/migrations/02_schema.sql.gz | mysql -uroot --socket=/var/run/mysqld/mysqld.sock --default-character-set=utf8mb4
echo ">>> Applying 01_seed.sql.gz"
zcat /testbed/migrations/01_seed.sql.gz | mysql -uroot --socket=/var/run/mysqld/mysqld.sock --default-character-set=utf8mb4 benchmark_db
echo ">>> Granting privileges"
mysql -uroot --socket=/var/run/mysqld/mysqld.sock <<'SQL'
GRANT ALL PRIVILEGES ON benchmark_db.* TO 'benchmark_user'@'%';
GRANT ALL PRIVILEGES ON benchmark_db.* TO 'benchmark_user'@'localhost';
GRANT SELECT, SHOW VIEW ON benchmark_db.* TO 'devops'@'%';
GRANT SELECT, SHOW VIEW ON benchmark_db.* TO 'devops'@'localhost';
FLUSH PRIVILEGES;
SQL
echo ">>> done"
